import com.midtermwork.*;import com.badlogic.gdx.*;import com.badlogic.gdx.graphics.*;import com.badlogic.gdx.backends.lwjgl3.*;
/** Runs actual reward mouse handlers with a framebuffer-aligned test pointer. */
public class RewardScreenCheck {static float[] pointer={-100,-100};static boolean click;
 public static void main(String[] args){final String dir=args.length>0?args[0]:"../build/reward-check";Lwjgl3ApplicationConfiguration c=new Lwjgl3ApplicationConfiguration();c.setTitle("midtermwork - clear reward verification");c.setWindowedMode(1152,648);c.setForegroundFPS(60);c.disableAudio(true);
 new Lwjgl3Application(new Main(p->{p[0]=pointer[0];p[1]=pointer[1];}){GameWorld w;int frames;GameWorld.Item selected;Object field(String name){try{java.lang.reflect.Field f=Main.class.getDeclaredField(name);f.setAccessible(true);return f.get(this);}catch(Exception ex){throw new RuntimeException(ex);}}
 public void create(){super.create();Input original=Gdx.input;Gdx.input=(Input)java.lang.reflect.Proxy.newProxyInstance(Input.class.getClassLoader(),new Class<?>[]{Input.class},(proxy,m,a)->{if(m.getName().equals("isKeyJustPressed")||m.getName().equals("isKeyPressed"))return false;if(m.getName().equals("isButtonJustPressed")){boolean result=click;click=false;return result;}return m.invoke(original,a);});w=(GameWorld)field("world");w.level=20;w.evolution=1;w.maxHp=w.hp=8;w.mapIndex=4;w.stageComplete=true;w.advanceStage();w.boss.hp=0;w.x=w.exitX()+2;w.step(1f/60,0,false,false);if(!w.choosingBuildReward())throw new AssertionError("build choice");}
 void point(int index){try{java.util.List<?> buttons=(java.util.List<?>)field("menuButtons");Object b=buttons.get(index);java.lang.reflect.Field f=b.getClass().getDeclaredField("rect");f.setAccessible(true);ItemHud.RenderedIcon r=(ItemHud.RenderedIcon)f.get(b);pointer[0]=(r.left+r.width/2)*Gdx.graphics.getWidth()/Gdx.graphics.getBackBufferWidth();pointer[1]=(r.top+r.height/2)*Gdx.graphics.getHeight()/Gdx.graphics.getBackBufferHeight();click=true;}catch(Exception ex){throw new RuntimeException(ex);}}
 void capture(String name){Pixmap p=Pixmap.createFromFrameBuffer(0,0,Gdx.graphics.getBackBufferWidth(),Gdx.graphics.getBackBufferHeight());java.io.File f=new java.io.File(dir,name+".png");f.getParentFile().mkdirs();PixmapIO.writePNG(Gdx.files.absolute(f.getAbsolutePath()),p,-1,true);p.dispose();}
 public void render(){frames++;if(frames==17)point(1);if(frames==32){selected=w.rewardItem(0);point(0);}super.render();if(frames==15)capture("build-choice");if(frames==18&& (w.choosingBuildReward()||w.buildRank(GameWorld.BuildPath.DASH)!=1))throw new AssertionError("build card click");if(frames==30)capture("item-choice");if(frames==33){if(w.choosingReward()||w.itemCount(selected)!=1)throw new AssertionError("tool card click");System.out.println("PASS: boss build choice then item choice, actual mouse handlers, aligned framebuffer cards");Gdx.app.exit();}}
 },c);}
}
